package claudecodeclillm

import "testing"

// The canonical JSON is shared with the TS constants (generated by
// a consuming app's own generator). These checks pin the Go
// half of that contract; the TS half is covered by claudeBaseModels.drift.test.ts.

func TestClaudeBaseAliasesLoadFromCanonicalJSON(t *testing.T) {
	aliases := ClaudeBaseAliases()
	if len(aliases) == 0 {
		t.Fatal("no aliases parsed from claude_base_models.json")
	}
	want := []string{"sonnet", "opus", "haiku", "fable"}
	if len(aliases) != len(want) {
		t.Fatalf("aliases = %v, want %v", aliases, want)
	}
	for i, a := range want {
		if aliases[i] != a {
			t.Errorf("aliases[%d] = %q, want %q", i, aliases[i], a)
		}
	}
}

func TestClaudeBaseModelPrefixesAreLongestFirst(t *testing.T) {
	prefixes := ClaudeBaseModelPrefixes()
	if len(prefixes) == 0 {
		t.Fatal("no prefixes derived")
	}
	for i := 1; i < len(prefixes); i++ {
		if len(prefixes[i-1]) < len(prefixes[i]) {
			t.Fatalf("prefixes not longest-first at %d: %v", i, prefixes)
		}
	}
}

func TestClaudeBaseModelsIncludeLabels(t *testing.T) {
	for _, m := range ClaudeBaseModels() {
		if m.Alias == "" || m.Label == "" {
			t.Errorf("tier missing alias/label: %+v", m)
		}
	}
}
